  Definition atUF0 (a0s : list byte) (L : Z) (T : TSet) : Prop :=
    forall vals R M,
      length vals = 198%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 112 = Z_to_bv 64 L ->
      regs_ok (ENV vals) u_srF0 R -> know_ok RSEGS (ENV vals) M u_knF0 ->
